/**
 * Hand poses for the glove models, transcribed from the legacy HandPoses.js
 * (generated by its HandPoseExtractor). Each pose has THUMB, INDEX and HAND
 * (middle, ring, pinky) groups; every bone lists its DEFAULT and PRESSED
 * local quaternions [x, y, z, w]. Animation slerps between them per group.
 */

export type Quat = [number, number, number, number];
export type BonePose = [defaultPose: Quat, pressedPose: Quat];
export type PoseGroup = Record<string, BonePose>;
export interface HandPose {
  THUMB: PoseGroup;
  INDEX: PoseGroup;
  HAND: PoseGroup;
}

